(function(){
const L=(latn,cyrl)=>`<div class="sept-lang sept-latn">${latn}</div><div class="sept-lang sept-cyrl">${cyrl}</div>`;
function insert(id,html){const article=document.querySelector(`#${CSS.escape(id)} article`);if(!article||article.querySelector('.september-extension'))return;const block=document.createElement('section');block.className='september-extension';block.innerHTML=html;const remember=article.querySelector('.remember');remember?remember.before(block):article.append(block)}
const examples=(title,items)=>`<h3>${title}</h3><div class="sept-example-grid">${items.map(x=>`<div class="sept-example"><span>${x[0]}</span><strong>${x[1]}</strong><p>${x[2]}</p></div>`).join('')}</div>`;
insert('ostatak',L(examples('Još rešenih primera',[
['PRIMER 1','17 : 5 = 3, ostatak 2','Provera: 17 = 5 · 3 + 2 i 0 ≤ 2 < 5.'],['PRIMER 2','38 : 6 = 6, ostatak 2','Najveći sadržalac broja 6 koji nije veći od 38 jeste 36. Zato je ostatak 38 − 36 = 2.'],['PRIMER 3','b = 9, q = 4, r = 3','Deljenik je a = b · q + r = 9 · 4 + 3 = 39.']]),examples('Још решених примера',[
['ПРИМЕР 1','17 : 5 = 3, остатак 2','Провера: 17 = 5 · 3 + 2 и 0 ≤ 2 < 5.'],['ПРИМЕР 2','38 : 6 = 6, остатак 2','Највећи садржалац броја 6 који није већи од 38 јесте 36. Зато је остатак 38 − 36 = 2.'],['ПРИМЕР 3','b = 9, q = 4, r = 3','Дељеник је a = b · q + r = 9 · 4 + 3 = 39.']])));
insert('jednacine',L(`<h3>Obnavljanje računanja i poretka</h3><p>Najpre računamo izraze u zagradama, zatim množimo i delimo, pa sabiramo i oduzimamo. Ako je <b>a &lt; b</b>, onda je <b>a + c &lt; b + c</b>.</p>`+examples('Rešeni primeri',[
['RAČUNSKE OPERACIJE','48 − 6 · 5 = 48 − 30 = 18','Množenje ima prednost nad oduzimanjem.'],['JEDNAČINA','3x + 5 = 26','3x = 21, pa je x = 7. Provera: 3 · 7 + 5 = 26.'],['NEJEDNAČINA','x + 3 < 7','U skupu N₀ rešenja su x ∈ {0, 1, 2, 3}.'],['POREDAK','27 < 35 ⇒ 27 + 8 < 35 + 8','Dodavanjem istog broja poredak se ne menja.']]),`<h3>Обнављање рачунања и поретка</h3><p>Најпре рачунамо изразе у заградама, затим множимо и делимо, па сабирамо и одузимамо. Ако је <b>a &lt; b</b>, онда је <b>a + c &lt; b + c</b>.</p>`+examples('Решени примери',[
['РАЧУНСКЕ ОПЕРАЦИЈЕ','48 − 6 · 5 = 48 − 30 = 18','Множење има предност над одузимањем.'],['ЈЕДНАЧИНА','3x + 5 = 26','3x = 21, па је x = 7. Провера: 3 · 7 + 5 = 26.'],['НЕЈЕДНАЧИНА','x + 3 < 7','У скупу N₀ решења су x ∈ {0, 1, 2, 3}.'],['ПОРЕДАК','27 < 35 ⇒ 27 + 8 < 35 + 8','Додавањем истог броја поредак се не мења.']])));
insert('pridruzivanje',L(`<p>Pravilo može biti sasvim jednostavno: broj preslikavamo u njegov sledbenik, prethodnik ili dvostruki broj. Svakom polaznom elementu mora odgovarati tačno jedan element.</p>`+examples('Rešeni primeri',[
['DVOSTRUKI BROJ','6 → 12','Pravilo je x → 2x.'],['SLEDBENIK','14 → 15','Pravilo je x → x + 1.'],['PRETHODNIK','20 → 19','Pravilo je x → x − 1.'],['OSOBINA','trougao → 3 stranice','Predmetu je pridružena njegova osobina.']]),`<p>Правило може бити сасвим једноставно: број пресликавамо у његов следбеник, претходник или двоструки број. Сваком полазном елементу мора одговарати тачно један елемент.</p>`+examples('Решени примери',[
['ДВОСТРУКИ БРОЈ','6 → 12','Правило је x → 2x.'],['СЛЕДБЕНИК','14 → 15','Правило је x → x + 1.'],['ПРЕТХОДНИК','20 → 19','Правило је x → x − 1.'],['ОСОБИНА','троугао → 3 странице','Предмету је придружена његова особина.']])));
insert('skupovi',L(examples('Važni primeri',[
['PRIPADANJE','4 ∈ {2, 4, 6}','Broj 4 je naveden kao element skupa.'],['NEPRIPADANJE','5 ∉ {2, 4, 6}','Broj 5 nije element datog skupa.'],['PRAZAN SKUP','{x ∈ N | x < 0} = ∅','Ne postoji prirodan broj manji od nule.'],['JEDNAKOST','{1, 2, 3} = {3, 1, 2}','Redosled elemenata ne menja skup.']]),examples('Важни примери',[
['ПРИПАДАЊЕ','4 ∈ {2, 4, 6}','Број 4 је наведен као елемент скупа.'],['НЕПРИПАДАЊЕ','5 ∉ {2, 4, 6}','Број 5 није елемент датог скупа.'],['ПРАЗАН СКУП','{x ∈ N | x < 0} = ∅','Не постоји природан број мањи од нуле.'],['ЈЕДНАКОСТ','{1, 2, 3} = {3, 1, 2}','Редослед елемената не мења скуп.']])));
insert('unija-presek',L(examples('Rešeni primeri',[
['UNIJA','{1, 2, 3} ∪ {3, 4} = {1, 2, 3, 4}','Uzimamo sve elemente, ali svaki zapisujemo samo jednom.'],['PRESEK','{1, 2, 3} ∩ {3, 4} = {3}','Uzimamo samo zajedničke elemente.'],['BEZ ZAJEDNIČKIH ELEMENATA','{1, 3} ∩ {2, 4} = ∅','Presek disjunktnih skupova je prazan skup.']]),examples('Решени примери',[
['УНИЈА','{1, 2, 3} ∪ {3, 4} = {1, 2, 3, 4}','Узимамо све елементе, али сваки записујемо само једном.'],['ПРЕСЕК','{1, 2, 3} ∩ {3, 4} = {3}','Узимамо само заједничке елементе.'],['БЕЗ ЗАЈЕДНИЧКИХ ЕЛЕМЕНАТА','{1, 3} ∩ {2, 4} = ∅','Пресек дисјунктних скупова је празан скуп.']])));
insert('razlika-skupova',L(examples('Kako zaključujemo sa dijagrama',[
['LEVI DEO','A ∖ B','Elementi koji su samo u skupu A.'],['PREKLOP','A ∩ B','Elementi koji pripadaju i skupu A i skupu B.'],['SVA TRI DELA','A ∪ B','Svi elementi koji su u bar jednom od skupova.']]),examples('Како закључујемо са дијаграма',[
['ЛЕВИ ДЕО','A ∖ B','Елементи који су само у скупу A.'],['ПРЕКЛОП','A ∩ B','Елементи који припадају и скупу A и скупу B.'],['СВА ТРИ ДЕЛА','A ∪ B','Сви елементи који су у бар једном од скупова.']])));
insert('lekcija',L(`<h3>Svojstva deljivosti</h3><p>Prvo posmatramo konkretne brojeve, a zatim izvodimo kratko pravilo.</p>`+examples('Rešeni primeri',[
['ZBIR','12 i 18 su deljivi sa 3','Zato je i 12 + 18 = 30 deljivo sa 3.'],['RAZLIKA','35 i 20 su deljivi sa 5','Zato je i 35 − 20 = 15 deljivo sa 5.'],['PROIZVOD','8 je deljivo sa 4','Zato je 8 · 7 = 56 deljivo sa 4.'],['PRENOS DELJIVOSTI','6 deli 24, a 3 deli 6','Zato 3 deli 24.']])+`<p class="sept-rule"><b>Pravilo:</b> ako su dva broja deljiva istim brojem, tada su njihov zbir i razlika deljivi tim brojem. Ako je jedan činilac deljiv brojem d, ceo proizvod je deljiv brojem d.</p>`,`<h3>Својства дељивости</h3><p>Прво посматрамо конкретне бројеве, а затим изводимо кратко правило.</p>`+examples('Решени примери',[
['ЗБИР','12 и 18 су дељиви са 3','Зато је и 12 + 18 = 30 дељиво са 3.'],['РАЗЛИКА','35 и 20 су дељиви са 5','Зато је и 35 − 20 = 15 дељиво са 5.'],['ПРОИЗВОД','8 је дељиво са 4','Зато је 8 · 7 = 56 дељиво са 4.'],['ПРЕНОС ДЕЉИВОСТИ','6 дели 24, а 3 дели 6','Зато 3 дели 24.']])+`<p class="sept-rule"><b>Правило:</b> ако су два броја дељива истим бројем, тада су њихов збир и разлика дељиви тим бројем. Ако је један чинилац дељив бројем d, цео производ је дељив бројем d.</p>`));
const finalIntro=document.querySelector('#zavrsni-test [data-i18n9="finalIntro"]');if(finalIntro){finalIntro.removeAttribute('data-i18n9');finalIntro.innerHTML=L('Test ima 20 zadataka iz ključnih sadržaja oblasti, sa posebnim naglaskom na septembarsko gradivo. Na kraju dobijaš procenu ocene i preporuku za dalji rad.','Тест има 20 задатака из кључних садржаја области, са посебним нагласком на септембарско градиво. На крају добијаш процену оцене и препоруку за даљи рад.')}
const classroomLessons=['ostatak','jednacine','pridruzivanje','skupovi','podskup','unija-presek','razlika-skupova','primena-skupova','skupovi-ds','lekcija'];
classroomLessons.forEach(id=>{const article=document.querySelector(`#${CSS.escape(id)} article`);if(!article||article.querySelector('.classroom-launch'))return;const title=article.querySelector('h2');if(!title)return;title.insertAdjacentHTML('afterend',`<a class="classroom-launch" href="/cas.html?id=${encodeURIComponent(id)}"><span aria-hidden="true">▶</span>${L('Pokreni čas','Покрени час')}</a>`)})
})();
